import sys

MOD = 998244353

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    M = int(data[1])
    S = data[2]

    size = 1 << N

    # match_masks[c] has bit i set iff S[i] == c
    match_masks = [0] * 26
    for i, ch in enumerate(S):
        match_masks[ord(ch) - 97] |= 1 << i

    # Count how many characters have each match mask
    freq = {}
    for cm in match_masks:
        freq[cm] = freq.get(cm, 0) + 1

    # popcount for each state
    pop = [0] * size
    for i in range(1, size):
        pop[i] = pop[i >> 1] + (i & 1)

    # Precompute transitions.
    # State mask: bit j is 1 iff dp[j+1] = dp[j] + 1,
    # where dp[j] = LCS(processed string, S[:j]).
    trans = []
    for mask in range(size):
        d = {}
        for cm, f in freq.items():
            old_prev = 0  # dp[j]
            new_prev = 0  # new_dp[j]
            nm = 0

            for j in range(N):
                old_cur = old_prev + ((mask >> j) & 1)  # dp[j+1]

                if (cm >> j) & 1:
                    # new_dp[j+1] = max(dp[j+1], new_dp[j], dp[j] + 1)
                    new_cur = old_cur
                    if new_prev > new_cur:
                        new_cur = new_prev
                    cand = old_prev + 1
                    if cand > new_cur:
                        new_cur = cand
                else:
                    # new_dp[j+1] = max(dp[j+1], new_dp[j])
                    new_cur = old_cur if old_cur > new_prev else new_prev

                if new_cur == new_prev + 1:
                    nm |= 1 << j

                old_prev = old_cur
                new_prev = new_cur

            d[nm] = d.get(nm, 0) + f

        trans.append(list(d.items()))

    # DP over length of the generated string
    vec = [0] * size
    vec[0] = 1

    for _ in range(M):
        nxt = [0] * size
        for mask, val in enumerate(vec):
            if val:
                for nm, cnt in trans[mask]:
                    nxt[nm] = (nxt[nm] + val * cnt) % MOD
        vec = nxt

    ans = [0] * (N + 1)
    for mask, val in enumerate(vec):
        if val:
            ans[pop[mask]] = (ans[pop[mask]] + val) % MOD

    print(" ".join(map(str, ans)))

if __name__ == "__main__":
    main()
```

