from typing import List

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        if not groups:
            return []

        max_group = max(groups)
        inf = len(elements) + 1

        # best[d] = smallest index of an element whose value is d
        best = [inf] * (max_group + 1)
        for idx, val in enumerate(elements):
            if val <= max_group and idx < best[val]:
                best[val] = idx

        # ans[g] = smallest element index that divides g
        ans = [inf] * (max_group + 1)

        for d in range(1, max_group + 1):
            idx = best[d]
            if idx != inf:
                for multiple in range(d, max_group + 1, d):
                    if idx < ans[multiple]:
                        ans[multiple] = idx

        return [ans[g] if ans[g] != inf else -1 for g in groups]
