class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        ans = 0

        for i, target in enumerate(nums):
            if target == 0:
                continue

            # Bitset DP: bit s is 1 iff sum s is reachable.
            reachable = 1
            mask = (1 << (target + 1)) - 1
            target_bit = 1 << target
            found = -1

            for j, (l, r, val) in enumerate(queries):
                if l <= i <= r:
                    reachable = (reachable | (reachable << val)) & mask
                    if reachable & target_bit:
                        found = j + 1
                        break

            if found == -1:
                return -1

            ans = max(ans, found)

        return ans
